def registry_factor(f: float) -> float:
    # denominator interpolation: open A=124 -> mature A=120.
    return 124.0 / (124.0 - 4.0 * f)

denom = log10_n_today - 3.0 * math.log10(1.0 + z_geom)
    if denom <= 0:
        return float("inf")
    return log10_n_today / denom

def _deu_freqs_local(f_gr, fc_hz, eta):
    f_gr = np.asarray(f_gr, dtype=float)
    if np.isinf(fc_hz):
        return eta * f_gr
    return float(fc_hz) * np.sin(float(eta) * f_gr / float(fc_hz))

def _strict_score(df):
    """Return DEU-vs-GR score only if DEU also beats uniform and free-scale controls."""
    gr = df["delta_BIC_DEU_vs_GR"].astype(float)
    u = df["delta_BIC_DEU_vs_UNIFORM_ETA_positive_favors_DEU"].astype(float)
    f = df["delta_BIC_DEU_vs_FREE_SCALE_positive_favors_DEU"].astype(float)
    return gr.where((u > 0) & (f > 0), -np.inf)

def _p_addone(n_ge, n):
    if n is None or n == 0:
        return np.nan
    return (1 + int(n_ge)) / (1 + int(n))

def deu_freqs(f_gr, fc, eta=ETA):
    f_gr = np.asarray(f_gr, dtype=float)
    if np.isinf(fc):
        return eta * f_gr
    return fc * np.sin(eta * f_gr / fc)
